// Claude Bridge — Nuendo / Cubase MIDI Remote driver script.
// GENERATED by nuendo_script/build.py — edit the template, not the output.
//
// Receives control messages from the nuendo-claude MCP server on the IAC bus
// "Claude to Nuendo" and reports state back as SysEx on "Claude from Nuendo".

var midiremote_api = require('midiremote_api_v1')

var CONFIG = /*__CONFIG__*/ {}

var deviceDriver = midiremote_api.makeDeviceDriver('Claude', 'Nuendo Bridge', 'nuendo-claude')
var midiInput = deviceDriver.mPorts.makeMidiInput()
var midiOutput = deviceDriver.mPorts.makeMidiOutput()

deviceDriver.makeDetectionUnit().detectPortPair(midiInput, midiOutput)
  .expectInputNameContains(CONFIG.portIn)
  .expectOutputNameContains(CONFIG.portOut)

var surface = deviceDriver.mSurface
var page = deviceDriver.mMapping.makePage('Claude')
var host = page.mHostAccess

// ------------------------------------------------------------------ feedback
var lastSent = {}

function send(activeDevice, obj, dedupeKey) {
  var s = JSON.stringify(obj)
  if (dedupeKey) {
    if (lastSent[dedupeKey] === s) return
    lastSent[dedupeKey] = s
  }
  var data = [0xF0, CONFIG.sysex[0], CONFIG.sysex[1]]
  for (var i = 0; i < s.length; i++) {
    var c = s.charCodeAt(i)
    data.push((c >> 14) & 0x7F, (c >> 7) & 0x7F, c & 0x7F)
  }
  data.push(0xF7)
  midiOutput.sendMidi(activeDevice, data)
}

function attachFeedback(surfaceValue, base) {
  // base: {t: 'sel'|'bank'|'tr', p: paramName, i?: slot}
  function ev(field, value) {
    var o = { t: base.t, p: base.p, f: field, v: value }
    if (base.i !== undefined) o.i = base.i
    return o
  }
  var key = base.t + ':' + base.p + ':' + (base.i === undefined ? '' : base.i)
  surfaceValue.mOnProcessValueChange = function (activeDevice, value) {
    send(activeDevice, ev('value', Math.round(value * 1000) / 1000), key + ':v')
  }
  surfaceValue.mOnDisplayValueChange = function (activeDevice, value, units) {
    send(activeDevice, ev('display', String(value) + (units ? ' ' + units : '')), key + ':d')
  }
  surfaceValue.mOnTitleChange = function (activeDevice, objectTitle, valueTitle) {
    send(activeDevice, ev('title', String(objectTitle)), key + ':t')
  }
}

// ------------------------------------------------------- surface element grid
var gridX = 0
var gridY = 0
function nextCell() {
  var cell = { x: gridX, y: gridY }
  gridX += 1
  if (gridX >= 32) { gridX = 0; gridY += 1 }
  return cell
}
function makeCCButton(channel, cc) {
  var c = nextCell()
  var b = surface.makeButton(c.x, c.y, 1, 1)
  b.mSurfaceValue.mMidiBinding.setInputPort(midiInput).bindToControlChange(channel, cc)
  return b
}
function makeCCKnob(channel, cc) {
  var c = nextCell()
  var k = surface.makeKnob(c.x, c.y, 1, 1)
  k.mSurfaceValue.mMidiBinding.setInputPort(midiInput).bindToControlChange(channel, cc)
  return k
}
function makeNoteButton(channel, note) {
  var c = nextCell()
  var b = surface.makeButton(c.x, c.y, 1, 1)
  b.mSurfaceValue.mMidiBinding.setInputPort(midiInput).bindToNote(channel, note)
  return b
}
function isToggleParam(name) {
  return name !== 'mVolume' && name !== 'mPan'
}

// ------------------------------------------------------------- key commands
for (var ci = 0; ci < CONFIG.commands.length; ci++) {
  var cmd = CONFIG.commands[ci]
  var btn = makeNoteButton(Math.floor(ci / 128), ci % 128)
  page.makeCommandBinding(btn.mSurfaceValue, cmd[0], cmd[1])
}

// ---------------------------------------------------------------- transport
for (var tName in CONFIG.transport) {
  var tVal = host.mTransport.mValue[tName]
  if (!tVal) continue
  var tb = makeCCButton(CONFIG.transportChannel, CONFIG.transport[tName])
  page.makeValueBinding(tb.mSurfaceValue, tVal)
  attachFeedback(tb.mSurfaceValue, { t: 'tr', p: tName })
}

// position read-out (API surface differs a little between versions; guard it)
try {
  host.mTransport.mTimeDisplay.mPrimary.mTransport.mOnChangePositionText = function (activeDevice) {
    var parts = []
    for (var a = 1; a < arguments.length; a++) {
      if (typeof arguments[a] === 'string') parts.push(arguments[a])
    }
    send(activeDevice, { t: 'pos', v: parts.join(' ').replace(/\s+/g, ' ') }, 'pos')
  }
} catch (e) { /* position feedback unavailable */ }

// --------------------------------------------------------------- mixer bank
var bankZone = host.mMixConsole.makeMixerBankZone('Claude Bank')
var bankChannels = []
for (var bi = 0; bi < CONFIG.bankSize; bi++) {
  var ch = bankZone.makeMixerBankChannel()
  bankChannels.push(ch)
  for (var bp in CONFIG.bank) {
    var hv = ch.mValue[bp]
    if (!hv) continue
    var el = isToggleParam(bp) ? makeCCButton(CONFIG.bank[bp], bi) : makeCCKnob(CONFIG.bank[bp], bi)
    page.makeValueBinding(el.mSurfaceValue, hv)
    attachFeedback(el.mSurfaceValue, { t: 'bank', p: bp, i: bi })
  }
}

// ------------------------------------------------------------ selected track
var sel = host.mTrackSelection.mMixerChannel
for (var sp in CONFIG.selected) {
  var sv = sel.mValue[sp]
  if (!sv) continue
  var sel_el = isToggleParam(sp) ? makeCCButton(CONFIG.selectedChannel, CONFIG.selected[sp])
                                 : makeCCKnob(CONFIG.selectedChannel, CONFIG.selected[sp])
  page.makeValueBinding(sel_el.mSurfaceValue, sv)
  attachFeedback(sel_el.mSurfaceValue, { t: 'sel', p: sp })
}
for (var si = 0; si < CONFIG.numSends; si++) {
  try {
    var slot = sel.mSends.getByIndex(si)
    var lk = makeCCKnob(CONFIG.selectedChannel, CONFIG.sendLevelCC + si)
    page.makeValueBinding(lk.mSurfaceValue, slot.mLevel)
    attachFeedback(lk.mSurfaceValue, { t: 'sel', p: 'send' + (si + 1) + 'Level' })
    var ob = makeCCButton(CONFIG.selectedChannel, CONFIG.sendOnCC + si)
    page.makeValueBinding(ob.mSurfaceValue, slot.mOn)
    attachFeedback(ob.mSurfaceValue, { t: 'sel', p: 'send' + (si + 1) + 'On' })
  } catch (e) { /* sends not available */ }
}
for (var qi = 0; qi < CONFIG.numQC; qi++) {
  try {
    var qk = makeCCKnob(CONFIG.selectedChannel, CONFIG.qcCC + qi)
    page.makeValueBinding(qk.mSurfaceValue, sel.mQuickControls.getByIndex(qi))
    attachFeedback(qk.mSurfaceValue, { t: 'sel', p: 'qc' + (qi + 1) })
  } catch (e) { /* quick controls not available */ }
}

// ------------------------------------------------------------------ actions
function resolveAction(path) {
  var parts = path.split('.')
  var obj = parts[0] === 'BANK' ? bankZone : host[parts[0]]
  for (var p = 1; p < parts.length && obj; p++) obj = obj[parts[p]]
  return obj
}
for (var aName in CONFIG.actions) {
  var spec = CONFIG.actions[aName]
  var action = resolveAction(spec[1])
  if (!action) continue
  var ab = makeNoteButton(CONFIG.actionChannel, spec[0])
  page.makeActionBinding(ab.mSurfaceValue, action)
}

// ---------------------------------------------------------------- lifecycle
deviceDriver.mOnActivate = function (activeDevice) {
  lastSent = {}
  send(activeDevice, { t: 'hello', v: 'Claude Bridge', commands: CONFIG.commands.length, bank: CONFIG.bankSize })
}
